/*
 * stub_nuttx.h — NuttX / hardware header stubs for PC simulator
 * Provides enough type/function declarations to compile board-side code
 * without any actual hardware.
 */
#ifndef __STUB_NUTTX_H
#define __STUB_NUTTX_H

#include <stdint.h>
#include <stdbool.h>
