/* ── uORB sensor stubs ── */
typedef int orb_advert_t;
typedef struct { int dummy; } sensor_light_t;

#define SENSOR_TYPE_LIGHT 0
#define ORB_SENSOR_LIGHT  "sensor_light"

static inline int orb_subscribe(int topic) { (void)topic; return -1; }
static inline int orb_subscribe_multi(int topic, int idx) {
