/*******************************************************************
 * deskmate_main.c — Simulator entry for deskmate_ui.c (board-same UI)
 *
 * Runs the exact UI code used on the R528 board (apps/luncher_dm/)
 * inside the PC simulator, so preview == board render.
 * Fonts: Montserrat 48/56/36/24/30/14 via freetype + FontAwesome symbols.
 *
 * Browser(ws://localhost:9009) → websockify → x11vnc(:5900) → Xvfb(:99) → lvglsim
 ******************************************************************/

#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "lvgl/lvgl.h"
#include "lvgl/src/libs/freetype/lv_freetype.h"
#include "src/lib/driver_backends.h"
#include "src/lib/simulator_util.h"
#include "src/lib/simulator_settings.h"
#include "deskmate_ui.h"

/* Global simulator settings */
extern simulator_settings_t settings;

/* Fonts consumed by deskmate_ui.c — provided here (simulator has no MiSans).
 * Assigned at runtime in main() as combo fonts (fa-solid → fa-brands →
 * montserrat) so LV_SYMBOL_* glyphs render from FontAwesome. */
lv_font_t *dm_font_title   = NULL; /* set in main() */
lv_font_t *dm_font_clock   = NULL; /* P151: status-bar time 56px */
lv_font_t *dm_font_symbol  = &lv_font_montserrat_48; /* replaced in main() */
lv_font_t *dm_font_icon    = NULL; /* set in main() */
lv_font_t *dm_font_body    = NULL; /* set in main() */
lv_font_t *dm_font_label   = NULL; /* set in main() */
lv_font_t *dm_font_caption = NULL; /* set in main() */

/* Dock glyphs are now native freetype labels — no transform scale needed */
int dm_symbol_scale = 256;

static char *selected_backend;

static void print_usage(void)
{
    printf("Usage: lvglsim [options]\n");
    printf("Options:\n");
    printf("  -b <backend>   Backend to use (SDL, WAYLAND, X11, DRM, FBDEV, GLFW)\n");
    printf("  -W <width>     Window width (default: 1920)\n");
    printf("  -H <height>    Window height (default: 1200)\n");
    printf("  -f             Fullscreen\n");
    printf("  -B             List supported backends\n");
    printf("  -h             Print this help\n");
    printf("\nExamples:\n");
    printf("  lvglsim -b SDL -W 1920 -H 1200\n");
}

static void configure_simulator(int argc, char **argv)
{
    int opt;
    const char *backend = "SDL";
    int width = 1920, height = 1200;
    int fullscreen = 0;

    while ((opt = getopt(argc, argv, "b:W:H:fhB")) != -1) {
        switch (opt) {
        case 'b':
            backend = optarg;
            break;
        case 'W':
            width = atoi(optarg);
            break;
        case 'H':
            height = atoi(optarg);
            break;
        case 'f':
            fullscreen = 1;
            break;
        case 'B':
            driver_backends_print_supported();
            exit(0);
        case 'h':
        default:
            print_usage();
            exit(0);
        }
    }

    selected_backend = strdup(backend);
    settings.window_width = width;
    settings.window_height = height;
    settings.rotation = LV_DISPLAY_ROTATION_0;
    settings.fullscreen = fullscreen;
    settings.maximize = false;
}

/* Combo font helper: make a font whose glyphs come from fa-solid first
 * (most LV_SYMBOL_*), then fa-brands (BLUETOOTH), then the montserrat text
 * fallback. */
static lv_font_t combo_fonts[6];
static lv_font_t *make_sym_font(int sz, const lv_font_t *text_fb, lv_font_t *out)
{
    lv_font_t *fs = lv_freetype_font_create("../fa-solid-900.ttf",
                                            LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                            sz, LV_FREETYPE_FONT_STYLE_NORMAL);
    lv_font_t *fb = lv_freetype_font_create("../fa-brands-400.ttf",
                                            LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                            sz, LV_FREETYPE_FONT_STYLE_NORMAL);
    if (fs == NULL) {
        LV_LOG_WARN("make_sym_font(%d): fa-solid-900.ttf load FAILED", sz);
        return (lv_font_t *)text_fb;
    }
    LV_LOG_WARN("make_sym_font(%d): fa-solid OK, fa-brands %s", sz, fb ? "OK" : "FAILED");
    *out = *fs;   /* copy dsc / get_glyph_dsc / get_glyph_bitmap from fa-solid */
    out->fallback = fb ? fb : text_fb;
    if (fb)
        fb->fallback = text_fb;
    return out;
}

int main(int argc, char **argv)
{
    configure_simulator(argc, argv);

    lv_init();

    /* FontAwesome dock glyphs via freetype (same as board) */
    dm_font_symbol = lv_freetype_font_create("../fa-solid-900.ttf",
                                             LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                             140, LV_FREETYPE_FONT_STYLE_NORMAL);
    if (dm_font_symbol == NULL)
        LV_LOG_WARN("fa-solid-900.ttf load failed, fallback to montserrat_48");

    /* LV_SYMBOL_* combo fonts — fa-solid → fa-brands → montserrat */
    dm_font_title   = make_sym_font(48, &lv_font_montserrat_48, &combo_fonts[0]);
    dm_font_clock   = make_sym_font(56, &lv_font_montserrat_48, &combo_fonts[1]);
    dm_font_icon    = make_sym_font(36, &lv_font_montserrat_36, &combo_fonts[2]);
    dm_font_body    = make_sym_font(24, &lv_font_montserrat_24, &combo_fonts[3]);
    dm_font_label   = make_sym_font(30, &lv_font_montserrat_30, &combo_fonts[4]);
    dm_font_caption = make_sym_font(14, &lv_font_montserrat_14, &combo_fonts[5]);

    driver_backends_register();

    if (driver_backends_init_backend(selected_backend) == -1)
        die("Failed to initialize display backend");

    /* Build the same UI as the board (deskmate_ui.c) */
    deskmate_ui_create();

    driver_backends_run_loop();
    return 0;
}

