/*******************************************************************
 * main_pet.c — Standalone pet demo for simulator
 *
 * Minimal entry: just LVGL + SDL + pet engine on a plain background.
 * No Desktop Mate UI, no lock screen, no standby — just the cat.
 ******************************************************************/

#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "lvgl/lvgl.h"
#include "lvgl/src/libs/freetype/lv_freetype.h"
#include "src/lib/driver_backends.h"
#include "src/lib/simulator_util.h"
#include "src/lib/simulator_settings.h"
#include "deskmate_ui.h"
#include "dm_pet.h"

extern simulator_settings_t settings;

/* Font globals required by deskmate_ui.h macros */
lv_font_t *dm_font_title   = NULL;
lv_font_t *dm_font_clock   = NULL;
lv_font_t *dm_font_symbol  = &lv_font_montserrat_48;
lv_font_t *dm_font_icon    = NULL;
lv_font_t *dm_font_body    = NULL;
lv_font_t *dm_font_label   = NULL;
lv_font_t *dm_font_caption = NULL;
int dm_symbol_scale = 256;

/* Fonts used by pet bubble text — need at least FONT_BODY */
static lv_font_t combo_fonts[3];
static lv_font_t montserrat_copies[3];
static lv_font_t *misans_fonts[3];

static lv_font_t *make_font(int sz, const lv_font_t *text_fb,
                            lv_font_t *out, lv_font_t *misans_fb,
                            lv_font_t *mont_copy)
{
    lv_font_t *fs = lv_freetype_font_create("/data/lv_port_linux/fa-solid-900.ttf",
                                            LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                            sz, LV_FREETYPE_FONT_STYLE_NORMAL);
    if (fs == NULL) return (lv_font_t *)text_fb;
    *out = *fs;
    out->fallback = mont_copy;
    *mont_copy = *text_fb;
    mont_copy->fallback = misans_fb;
    return out;
}

static void log_print_cb(lv_log_level_t level, const char *buf)
{
    (void)level;
    printf("%s\n", buf);
}

int main(int argc, char **argv)
{
    (void)argc; (void)argv;

    settings.window_width = 400;
    settings.window_height = 600;
    settings.rotation = LV_DISPLAY_ROTATION_0;
    settings.fullscreen = 0;
    settings.maximize = false;

    lv_init();
    lv_log_register_print_cb(log_print_cb);

    /* Load MiSans for Chinese pet bubble text */
    misans_fonts[0] = lv_freetype_font_create("/data/lv_port_linux/MiSans-Normal.ttf",
                                              LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                              24, LV_FREETYPE_FONT_STYLE_NORMAL);
    misans_fonts[1] = lv_freetype_font_create("/data/lv_port_linux/MiSans-Normal.ttf",
                                              LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                              30, LV_FREETYPE_FONT_STYLE_NORMAL);
    misans_fonts[2] = lv_freetype_font_create("/data/lv_port_linux/MiSans-Normal.ttf",
                                              LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                              14, LV_FREETYPE_FONT_STYLE_NORMAL);

    dm_font_body    = make_font(24, &lv_font_montserrat_24, &combo_fonts[0], misans_fonts[0], &montserrat_copies[0]);
    dm_font_label   = make_font(30, &lv_font_montserrat_30, &combo_fonts[1], misans_fonts[1], &montserrat_copies[1]);
    dm_font_caption = make_font(14, &lv_font_montserrat_14, &combo_fonts[2], misans_fonts[2], &montserrat_copies[2]);

    driver_backends_register();
    if (driver_backends_init_backend("SDL") == -1) {
        printf("Failed to init SDL backend\n");
        return 1;
    }

    /* Plain dark background */
    lv_obj_t *scr = lv_scr_act();
    lv_obj_set_style_bg_color(scr, lv_color_hex(0x1C1C1E), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);

    /* Create pet directly on screen */
    dm_pet_create(scr);
    dm_pet_on_event(PET_EVT_SLEEP);

    printf("Pet demo running! Close window to exit.\n");
    driver_backends_run_loop();
    return 0;
}

