static void make_body_font(void)
{
    lv_font_t *fa = lv_freetype_font_create("/data/lv_port_linux/fa-solid-900.ttf",
                                            LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                            24, LV_FREETYPE_FONT_STYLE_NORMAL);
    if (fa) {
        combo_body = *fa;
        combo_body.fallback = &mont_body;
    }
    mont_body = lv_font_montserrat_24;
    mont_body.fallback = misans_body;
    dm_font_body = fa ? &combo_body : &mont_body;
    dm_font_label = dm_font_body;
    dm_font_caption = dm_font_body;
    dm_font_title = dm_font_body;
    dm_font_clock = dm_font_body;
    dm_font_icon = dm_font_body;
}

static void log_print_cb(lv_log_level_t level, const char *buf)
{
    (void)level;
    printf("%s\n", buf);
}

int main(int argc, char **argv)
{
    (void)argc; (void)argv;

    settings.window_width = 1920;
    settings.window_height = 1200;
    settings.rotation = LV_DISPLAY_ROTATION_0;
    settings.fullscreen = 0;
    settings.maximize = false;

    lv_init();
    lv_log_register_print_cb(log_print_cb);

    /* Load MiSans for Chinese pet bubble text */
    misans_body = lv_freetype_font_create("/data/lv_port_linux/MiSans-Normal.ttf",
                                          LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                          24, LV_FREETYPE_FONT_STYLE_NORMAL);
    if (misans_body)
        printf("[petdemo] MiSans loaded OK\n");
    else
        printf("[petdemo] MiSans FAILED\n");

    make_body_font();

    driver_backends_register();
    if (driver_backends_init_backend("SDL") == -1) {
        printf("Failed to init SDL backend\n");
        return 1;
    }

    /* Plain background */
    lv_obj_t *scr = lv_scr_act();
    lv_obj_set_style_bg_color(scr, lv_color_hex(0x2C2C2E), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);

    /* Create pet directly on screen */
    int ret = dm_pet_create(scr);
    printf("[petdemo] dm_pet_create returned %d\n", ret); fflush(stdout);
    dm_pet_on_event(PET_EVT_SLEEP);
    printf("[petdemo] Pet demo running! Close window to exit.\n"); fflush(stdout);

    driver_backends_run_loop();
    return 0;
}

